import React, { useState } from 'react';
import './signup.css';

function SignupForm() {
  const [formData, setFormData] = useState({ username: '', email: '', password: '' });
  const [otp, setOtp] = useState('');
  const [step, setStep] = useState('signup'); 
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');
    setMessage('');
    setLoading(true);

    try {
      // Save signup details to localStorage
      const existingUsers = JSON.parse(localStorage.getItem('users')) || [];
      existingUsers.push({ ...formData, id: Date.now() });
      localStorage.setItem('users', JSON.stringify(existingUsers));

      setStep('otp');
      setMessage('✅ OTP simulated. Please verify.'); // Simulated OTP
    } catch (err) {
      setError('Signup failed');
    } finally {
      setLoading(false);
    }
  };

  const handleOtpSubmit = (e) => {
    e.preventDefault();
    setError('');
    setMessage('');
    setLoading(true);

    // Simulate OTP verification
    if (otp === '1234') {
      setStep('done');
      setMessage('🎉 Signup successful! User saved to Admin Dashboard.');
    } else {
      setError('Invalid OTP. Use 1234');
    }
    setLoading(false);
  };

  const handleResendOtp = () => {
    setMessage('🔄 OTP resent (simulated)');
  };

  return (
    <div className="signup-container">
      <div className="signup-box">
        {step === 'signup' && (
          <>
            <h2>Sign Up</h2>
            <form onSubmit={handleSubmit}>
              <input
                type="text"
                name="username"
                placeholder="Username"
                value={formData.username}
                onChange={handleChange}
                required
              />
              <input
                type="email"
                name="email"
                placeholder="Email"
                value={formData.email}
                onChange={handleChange}
                required
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                value={formData.password}
                onChange={handleChange}
                required
              />
              <button type="submit" disabled={loading}>
                {loading ? 'Signing Up...' : 'Sign Up'}
              </button>
            </form>
          </>
        )}

        {step === 'otp' && (
          <>
            <h2>Verify OTP</h2>
            <form onSubmit={handleOtpSubmit}>
              <input
                type="text"
                placeholder="Enter OTP (use 1234)"
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
                required
              />
              <button type="submit" disabled={loading}>
                {loading ? 'Verifying...' : 'Verify'}
              </button>
            </form>
            <p style={{ marginTop: '10px' }}>
              Didn’t get OTP?{' '}
              <button type="button" onClick={handleResendOtp} style={{ color: 'blue', background: 'none', border: 'none', cursor: 'pointer' }}>
                Resend
              </button>
            </p>
          </>
        )}

        {step === 'done' && (
          <div style={{ textAlign: 'center' }}>
            <h2>✅ Signup Complete</h2>
            <p>User details saved in Admin Dashboard.</p>
          </div>
        )}
        {message && <p style={{ color: 'green' }}>{message}</p>}
        {error && <p style={{ color: 'red' }}>{error}</p>}
      </div>
    </div>
  );
}

export default SignupForm;
